#!/usr/bin/env node
// Offline check of the TOKENED branch of the colorcombinations /go/ gate.
//
// WHY: scripts/verify-gate.sh probes production TOKENLESS on purpose (a valid token would fabricate
// an affiliate click), so it is bounced home before the tagged-redirect branch runs and cannot see a
// crash or a wrong destination on a REAL click. That blind spot hid dormbyschool's /go/s crash for
// 10 days (2026-09-05..15). Here two more silent failures are possible: /go/b only redirects a
// checksum-valid ISBN-10, and the chunked deploy ships dist/_worker.js generated by
// scripts/make-worker.mjs, whose try/catch serves the static asset on a throw (a crash reads as 200).
//
// WHAT: runs BOTH the functions/go/* sources and the shipped dist/_worker.js as pure computation,
// replaying every distinct /go/ href in dist/*.html the way the click handler sends it (?t=<base36
// now>, and separately the cc_g cookie) with a real navigation's headers, from the US and from an
// EU-routed country. Location is compared with an independent reading of the routing rules.
// No request leaves this machine; no Amazon URL is fetched. Also fail-closed and sabotage controls.
// Usage: node scripts/verify-gate-offline.mjs [distDir]   (exit 0 = pass, 1 = fail)
import fs from 'node:fs';
import path from 'node:path';

// No network, ever. If a gate one day beacons server-side (fetch to a click counter), running this check on every
// deploy must not turn into thousands of fake clicks: every fetch the code under test makes is recorded, answered
// locally with 204, and never leaves this machine.
const NET = [];
globalThis.fetch = async (u) => { NET.push(String((u && u.url) || u)); return new Response(null, { status: 204 }); };
process.on('exit', () => { if (NET.length) console.log(`note: ${NET.length} fetch call(s) from the gate were answered locally, e.g. ${NET[0]}`); });

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const DIST = path.resolve(process.argv[2] || path.join(ROOT, 'dist'));
const WORKER = path.join(DIST, '_worker.js');
const ORIGIN = 'https://colorcombinations.org';
const TAG = 'colorcombinations-20';
const EU_TAG = 'caslonmedia-21';
const EU_ROUTED = new Set(['AT', 'BE', 'LU', 'PT', 'IE', 'CZ', 'SK', 'SI', 'HU', 'RO', 'BG', 'HR', 'GR', 'DK', 'FI', 'EE', 'LV', 'LT', 'CY', 'MT']);
const PRIME = 'https://www.amazon.com/amazonprime?&linkCode=ll2&tag=colorcombinations-20&linkId=ce478672978b2ae0d059c64c9d3641f5&language=en_US&ref_=as_li_ss_tl';
const NAV = { 'sec-fetch-mode': 'navigate', 'sec-fetch-site': 'same-origin', 'sec-fetch-user': '?1' };
const env = { ASSETS: { fetch: async () => new Response('asset', { status: 200 }) } };
const mod = (src) => import('data:text/javascript,' + encodeURIComponent(src));

const isbn10 = (s) => /^[0-9]{9}[0-9Xx]$/.test(s) && [...s].reduce((a, c, i) => a + (10 - i) * (/x/i.test(c) ? 10 : +c), 0) % 11 === 0;
// US visitors get the tagged search for listings with no new US offer (2026-10-03, card
// mus7y2u86ihabr). Mirrors US_TO_SEARCH in functions/go/b and TO_SEARCH in functions/go/p; keep
// all three in sync. Every other id and every other country must still land on /dp/.
const US_SEARCH = {
  b: { '0714873896': 'https://www.amazon.com/s?k=Chromaphilia%20Stella%20Paul&i=stripbooks' },
  p: { B0DPN7L6L5: 'https://www.amazon.com/s?k=Calibrite%20Display%20Plus%20HL%20colorimeter' },
};
function expected(href, country) {
  const u = new URL(href, ORIGIN);
  const c = u.searchParams.get('c');
  const st = c && /^[a-z0-9-]{1,32}$/.test(c) ? `&ascsubtag=${c}` : '';
  let m = u.pathname.match(/^\/go\/p\/([A-Za-z0-9]{10})\/?$/);
  if (m) return country === 'US' && US_SEARCH.p[m[1].toUpperCase()] ? `${US_SEARCH.p[m[1].toUpperCase()]}&tag=${TAG}${st}` : `https://www.amazon.com/dp/${m[1].toUpperCase()}?tag=${TAG}${st}`;
  m = u.pathname.match(/^\/go\/b\/([0-9Xx]{10})\/?$/);
  if (m) {
    if (!isbn10(m[1])) return null;
    const [host, tag] = EU_ROUTED.has(country) ? ['www.amazon.de', EU_TAG] : ['www.amazon.com', TAG];
    if (country === 'US' && US_SEARCH.b[m[1].toUpperCase()]) return `${US_SEARCH.b[m[1].toUpperCase()]}&tag=${tag}${st}`;
    return `https://${host}/dp/${m[1].toUpperCase()}?tag=${tag}${st}`;
  }
  if (/^\/go\/prime\/?$/.test(u.pathname)) return PRIME;
  return null;
}

// Handlers keyed by route, from the sources; and the shipped worker as one handler.
async function fromSources(patch = (s) => s) {
  const read = (f) => patch(fs.readFileSync(path.join(ROOT, f), 'utf8'));
  const p = (await mod(read('functions/go/p/[[asin]].js'))).onRequestGet;
  const b = (await mod(read('functions/go/b/[[isbn]].js'))).onRequestGet;
  const pr = (await mod(read('functions/go/prime.js'))).onRequestGet;
  return (request) => {
    const pn = new URL(request.url).pathname;
    const h = pn.startsWith('/go/p/') ? p : pn.startsWith('/go/b/') ? b : /^\/go\/prime\/?$/.test(pn) ? pr : null;
    return h ? h({ request }) : new Response('no route (Pages 404)', { status: 404 });
  };
}
async function fromWorker(patch = (s) => s) {
  const w = (await mod(patch(fs.readFileSync(WORKER, 'utf8')))).default;
  return (request) => w.fetch(request, env, {});
}

async function call(handler, href, { headers = NAV, mint = 'query', country = 'US', t } = {}) {
  const u = new URL(href, ORIGIN);
  const tok = t ?? Date.now().toString(36);
  const h = { ...headers, 'cf-ipcountry': country };
  if (mint === 'query') u.searchParams.set('t', tok);
  if (mint === 'cookie') h.cookie = `cc_g=${tok}`;
  try {
    const r = await handler(new Request(u.href, { headers: h }));
    return { status: r.status, loc: r.headers.get('location') || '' };
  } catch (e) {
    return { status: 'THROW', loc: `${e.name}: ${e.message}` };
  }
}

function builtHrefs(dir) {
  const set = new Set();
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const f = path.join(d, e.name);
      if (e.isDirectory()) walk(f);
      else if (e.name.endsWith('.html')) for (const m of fs.readFileSync(f, 'utf8').matchAll(/href="(\/go\/[^"]*)"/g)) set.add(m[1].replace(/&amp;/g, '&'));
    }
  };
  walk(dir);
  return [...set];
}

async function run(handler, hrefs, quiet, isWorker) {
  let failed = 0;
  const say = (ok, msg) => { if (!ok) failed++; if (!quiet) console.log(`${ok ? 'PASS' : 'FAIL'}  ${msg}`); };
  for (const country of ['US', 'AT']) {
    const byShape = {};
    for (const href of hrefs) {
      const want = expected(href, country);
      const shape = (href.match(/^\/go\/[a-z]+/) || ['?'])[0];
      byShape[shape] = byShape[shape] || { n: 0, bad: 0 };
      byShape[shape].n++;
      const got = await call(handler, href, { country });
      if (!(want !== null && got.status === 302 && got.loc === want)) {
        failed++;
        if (++byShape[shape].bad <= 5 && !quiet) console.log(`FAIL  [${country}] built href ${href} [${got.status}] ${got.loc}  want ${want}`);
      }
    }
    if (!quiet) for (const [s, v] of Object.entries(byShape)) console.log(`${v.bad ? 'FAIL' : 'PASS'}  [${country}] ${s}: ${v.n - v.bad}/${v.n} built hrefs → exact tagged Amazon URL`);
  }
  for (const s of ['/go/p/', '/go/b/', '/go/prime']) {
    const href = hrefs.find((h) => h.startsWith(s));
    if (!href) continue;
    const g = await call(handler, href, { mint: 'cookie' });
    say(g.status === 302 && g.loc === expected(href, 'US'), `ctl cookie-minted ${s} [${g.status}] ${g.loc.slice(0, 60)}`);
  }
  const sample = hrefs.find((h) => h.startsWith('/go/p/')) || '/go/p/B000KNLQIM';
  const home = `${ORIGIN}/`;
  const ctl = async (label, href, o) => { const g = await call(handler, href, o); say(g.status === 302 && g.loc === home, `ctl ${label} → home [${g.status}] ${g.loc}`); };
  await ctl('tokenless', sample, { mint: 'none' });
  await ctl('no Sec-Fetch headers', sample, { headers: {} });
  await ctl('cross-site navigation', sample, { headers: { 'sec-fetch-mode': 'navigate', 'sec-fetch-site': 'cross-site' } });
  await ctl('stale token (2h)', sample, { t: (Date.now() - 7_200_000).toString(36) });
  await ctl('forged token', sample, { t: 'ZZZZZZ' });
  await ctl('checksum-invalid ISBN', '/go/b/1234567890', {});
  // Only the shipped worker owns unmatched /go/ paths; with bare functions/ Pages would 404 them.
  if (isWorker) await ctl('unknown shape /go/x', '/go/x/B000KNLQIM', {});
  return failed;
}

const hrefs = builtHrefs(DIST);
if (hrefs.length < 50) { console.log(`FAIL  only ${hrefs.length} /go/ hrefs found in ${DIST} — instrument blind (build missing?)`); process.exit(1); }
if (!fs.existsSync(WORKER)) { console.log(`FAIL  ${WORKER} missing — the chunked deploy would ship no gate`); process.exit(1); }
const sabotage = (s) => s.replace('`https://www.amazon.com/dp/${m[1].toUpperCase()}?tag=${TAG}`', '`https://www.amazon.com/gp/${m[1].toUpperCase()}?tag=${TAG}`');
let total = 0;
for (const [name, build, isWorker] of [['functions/go/* (source)', fromSources, false], ['dist/_worker.js (shipped)', fromWorker, true]]) {
  console.log(`\n== ${name}`);
  total += await run(await build(), hrefs, false, isWorker);
  const sab = await run(await build(sabotage), hrefs, true, isWorker);
  const ok = sab > 0;
  if (!ok) total++;
  console.log(`${ok ? 'PASS' : 'FAIL'}  sabotage control: a copy routing /go/p to /gp/ fails ${sab} checks`);
}
const w = await fromWorker();
const r = await w(new Request(`${ORIGIN}/colors/navy/`));
if (r.status !== 200) total++;
console.log(`${r.status === 200 ? 'PASS' : 'FAIL'}  worker serves non-/go/ paths from ASSETS [${r.status}]`);
console.log(total ? `\n${total} FAILED (${hrefs.length} built hrefs)` : `\nall checks passed: ${hrefs.length} built hrefs x 2 countries x 2 artifacts + controls`);
process.exit(total ? 1 : 0);
